import{d as g,C as n,o as h,c as u,a3 as i,E as a,j as t,a as d}from"./chunks/framework.Q4yG9rk_.js";const c=JSON.parse('{"title":"论语·先进","description":"《论语》第 11 篇「先进」——二十六章原文与导读。四科十哲、未知生焉知死、过犹不及、求也退故进之，以及「吾与点也」的侍坐章。","frontmatter":{"title":"论语·先进","description":"《论语》第 11 篇「先进」——二十六章原文与导读。四科十哲、未知生焉知死、过犹不及、求也退故进之，以及「吾与点也」的侍坐章。","category":"guide","aliases":["先进","先进篇","先进第十一","论语先进","lunyu 先进"],"source":["《论语》"],"outline":[2,3]},"headers":[],"relativePath":"lizhimingde/sishu-wujing/lunyu/chapter-11.md","filePath":"lizhimingde/sishu-wujing/lunyu/chapter-11.md","lastUpdated":1790316338000}'),m={name:"lizhimingde/sishu-wujing/lunyu/chapter-11.md"},w=g({...m,setup(p){const s=[{id:"yi",label:"一、先进于礼乐，野人也",showLabel:!0,sentences:[["子曰：“先进于礼乐，野人也；后进于礼乐，君子也。如用之，则吾从先进。”"]],note:"「先进于礼乐，野人也；后进于礼乐，君子也」——先辈行用礼乐时质朴无文，像乡野之人；后辈行用礼乐时文饰渐多，像君子。「如用之，则吾从先进」——若要用，我宁取先辈的质朴。此章异解甚多，一说「先进」指先入仕而后学礼乐者。"},{id:"er",label:"二、从我于陈蔡者",showLabel:!0,sentences:[["子曰：“从我于陈、蔡者，皆不及门也。”"]],note:"「从我于陈、蔡者，皆不及门也」——当年跟随我在陈、蔡之间受困的学生们，如今都不在我门下了。此为怀旧之叹。"},{id:"san",label:"三、四科十哲",showLabel:!0,sentences:[["德行：颜渊，闵子骞，冉伯牛，仲弓。言语：宰我，子贡。政事：冉有，季路。文学：子游，子夏。"]],note:"此章列孔门「四科十哲」：德行——颜渊、闵子骞、冉伯牛、仲弓；言语——宰我、子贡；政事——冉有、季路；文学——子游、子夏。为孔门人才分类之总表。"},{id:"si",label:"四、回也非助我者也",showLabel:!0,sentences:[["子曰：“回也非助我者也，于吾言无所不说。”"]],note:"「回也非助我者也，于吾言无所不说（悦）」——颜回不是能帮助我的人，因他于我的话没有不喜欢的（即无所质疑、无所发明）。语似责而实为叹。"},{id:"wu",label:"五、孝哉闵子骞",showLabel:!0,sentences:[["子曰：“孝哉闵子骞！人不",{text:"间",glossary:"jian-jian"},"于其父母昆弟之言。”"]],note:"「孝哉闵子骞！人不间于其父母昆弟之言」——闵子骞真孝啊！人们对他父母兄弟称赞他的话，没有非议（间＝非议、离间）。言其孝出于至诚，人无异辞。"},{id:"liu",label:"六、南容三复白圭",showLabel:!0,sentences:[["南容三复白圭，孔子以其兄之子妻之。"]],note:"「南容三复白圭」——南容反复诵读《诗》中「白圭之玷」几句（以慎言自警）；孔子便把哥哥的女儿嫁给了他。"},{id:"qi",label:"七、有颜回者好学",showLabel:!0,sentences:[["季康子问：“弟子孰为好学？”孔子对曰：“有颜回者好学，不幸短命死矣，今也则亡。”"]],note:"季康子问：弟子中谁好学？孔子答：「有颜回者好学，不幸短命死矣，今也则亡（无）」——有个颜回好学，不幸短命而死，如今没有这样的人了。（与《雍也》第三章略同。）"},{id:"ba",label:"八、才不才，亦各言其子也",showLabel:!0,sentences:[["颜渊死，颜路请子之车以为之",{text:"椁",glossary:"guo"},"。子曰：“才不才，亦各言其子也。鲤也死，有棺而无椁，吾不徒行以为之椁。以吾从大夫之后，不可徒行也。”"]],note:"颜渊死，颜路（颜渊之父）请求用孔子的车给颜渊做外棺（椁）。孔子说：「才不才，亦各言其子也」——无论有才与否，各人都会说到自己的儿子。「鲤也死，有棺而无椁」——我的儿子孔鲤死时，也只有棺而无椁。「吾不徒行以为之椁，以吾从大夫之后，不可徒行也」——我不能步行而把车让出去做椁，因为我忝居大夫之列，不可以徒步而行。"},{id:"jiu",label:"九、天丧予",showLabel:!0,sentences:[["颜渊死。子曰：“噫！天丧予！天丧予！”"]],note:"颜渊死。孔子说：「噫！天丧予！天丧予」——唉！老天要我的命啊！老天要我的命啊！两叹连声，极哀。"},{id:"shi",label:"十、非夫人之为恸而谁为",showLabel:!0,sentences:[["颜渊死，子哭之",{text:"恸",glossary:"tong"},"，从者曰：“子恸矣！”曰：“有恸乎？非夫人之为恸而谁为？”"]],note:"颜渊死，孔子哭之极恸。随从者说：「子恸矣」——您太悲痛了！孔子说：「有恸乎」——真有那么悲痛吗？「非夫人之为恸而谁为」——我不为这个人悲痛，还为谁悲痛呢？"},{id:"shiyi",label:"十一、予不得视犹子也",showLabel:!0,sentences:[["颜渊死，门人欲厚葬之。子曰：“不可。”门人厚葬之，子曰：“回也视予犹父也，予不得视犹子也。非我也，夫二三子也！”"]],note:"颜渊死，门人欲厚葬之。孔子说「不可」，门人竟厚葬了。孔子说：「回也视予犹父也，予不得视犹子也」——颜回待我如父，我却不能待他如子（谓不得以父之礼主其丧）。「非我也，夫二三子也」——这不是我的意思，是那些学生们做的。"},{id:"shier",label:"十二、未知生，焉知死",showLabel:!0,sentences:[["季路问事鬼神，子曰：“未能事人，焉能事鬼？”曰：“敢问死。”曰：“未知生，焉知死？”"]],note:"季路问怎样服事鬼神。孔子说：「未能事人，焉能事鬼」——还不能服事人，怎能服事鬼？又问死，答：「未知生，焉知死」——还不知道生，怎能知道死？此章见孔子不轻言鬼神与死。"},{id:"shisan",label:"十三、若由也，不得其死然",showLabel:!0,sentences:[["闵子侍侧，",{text:"訚訚如",glossary:"yinyinru2"},"也；子路，",{text:"行行如",glossary:"hanghangru"},"也；冉有、子贡，",{text:"侃侃如",glossary:"kankanru2"},"也。子乐。“若由也，不得其死然。”"]],note:"闵子骞侍立于侧，和悦而正直（訚訚如也）；子路刚强（行行如也）；冉有、子贡刚直而和乐（侃侃如也）。孔子很高兴。又说：「若由也，不得其死然」——像仲由这般刚强，怕不得善终啊。（后子路果死于卫乱。）"},{id:"shisi",label:"十四、夫人不言，言必有中",showLabel:!0,sentences:[["鲁人为长府，闵子骞曰：“仍旧贯如之何？何必改作？”子曰：“夫人不言，言必有中。”"]],note:"鲁国改建名叫长府的库藏。闵子骞说：「仍旧贯如之何？何必改作」——照旧例如何？何必改建？孔子说：「夫人不言，言必有中」——此人平日不大开口，一开口必中要害。"},{id:"shiwu",label:"十五、由也升堂矣，未入于室也",showLabel:!0,sentences:[["子曰：“由之瑟奚为于丘之门？”门人不敬子路，子曰：“由也升堂矣，未入于室也。”"]],note:"「由之瑟奚为于丘之门」——仲由弹瑟，何以在我这里弹（谓其声刚猛不和）？门人因此不敬子路。孔子说：「由也升堂矣，未入于室也」——仲由已升堂了，只是尚未入室。既抑其过，又护其学。"},{id:"shiliu",label:"十六、过犹不及",showLabel:!0,sentences:[["子贡问：“师与商也孰贤？”子曰：“师也过，商也不及。”曰：“然则师愈与？”子曰：“",{text:"过犹不及",glossary:"guoyoubuji"},"。”"]],note:"子贡问：「师与商也孰贤」——颛孙师（子张）与卜商（子夏）谁更贤？孔子说：「师也过，商也不及」——子张有些过头，子夏有所不足。问：「然则师愈与」——那么子张更强吗？答：「过犹不及」——过头与不足是一样的。"},{id:"shiqi",label:"十七、非吾徒也",showLabel:!0,sentences:[["季氏富于周公，而求也为之聚敛而附益之。子曰：“非吾徒也。小子鸣鼓而攻之可也。”"]],note:"季氏比周公还富有，而冉求仍为他聚敛，使其更富。孔子说：「非吾徒也。小子鸣鼓而攻之可也」——他不是我的门徒了！你们可以鸣鼓而攻之。"},{id:"shiba",label:"十八、柴也愚，参也鲁",showLabel:!0,sentences:[["柴也愚，参也鲁，师也",{text:"辟",glossary:"pi-pian"},"，由也",{text:"喭",glossary:"yan"},"。"]],note:"「柴也愚，参也鲁，师也辟，由也喭」——高柴愚直，曾参迟钝，颛孙师偏激（辟＝偏），仲由鲁莽（喭＝粗鲁）。四句各指其气质之偏。"},{id:"shijiu",label:"十九、回也其庶乎，屡空",showLabel:!0,sentences:[["子曰：“回也其庶乎，",{text:"屡空",glossary:"lvkong"},"。赐不受命而货殖焉，",{text:"亿则屡中",glossary:"yizelvzhong"},"。”"]],note:"「回也其庶乎，屡空」——颜回的修养近于道了吧，却常常穷乏（空＝贫穷）。「赐不受命而货殖焉，亿（臆）则屡中」——子贡不受命而经商，揣度行情却常猜中。二子一贫一富，两相对照。"},{id:"ershi",label:"二十、不践迹，亦不入于室",showLabel:!0,sentences:[["子张问善人之道，子曰：“不践迹，亦不入于室。”"]],note:"子张问善人之道。孔子说：「不践迹，亦不入于室」——不践前人之迹，也就不能入于深奥之室。一说谓善人自然合道，不必践迹，然亦未能入圣人之室。"},{id:"ershiyi",label:"二十一、论笃是与",showLabel:!0,sentences:[["子曰：“论",{text:"笃",glossary:"du"},"是与，君子者乎？色庄者乎？”"]],note:"「论笃是与，君子者乎？色庄者乎」——我所称许的是言论笃实之人；但他是真君子呢，还是只神色庄重而内不然？言观人当察其实。"},{id:"ershier",label:"二十二、求也退，故进之",showLabel:!0,sentences:[["子路问：“闻斯行诸？”子曰：“有父兄在，如之何其闻斯行之？”冉有问：“闻斯行诸？”子曰：“闻斯行之。”公西华曰：“由也问闻斯行诸，子曰有父兄在；求也问闻斯行诸，子曰闻斯行之。赤也惑，敢问。”子曰：“求也退，故进之；由也兼人，故退之。”"]],note:"子路问：「闻斯行诸」——听到该做之事便去做吗？孔子说：「有父兄在，如之何其闻斯行之」——有父兄在，怎可听到就做？冉有问同样的问题，孔子说：「闻斯行之」。公西华惑而问，孔子说：「求也退，故进之；由也兼人，故退之」——冉求退缩，故我推他一把；仲由勇过两人，故我压他一压。此为因材施教之典范。"},{id:"ershisan",label:"二十三、子在，回何敢死",showLabel:!0,sentences:[["子畏于匡，颜渊后。子曰：“吾以女为死矣！”曰：“子在，回何敢死？”"]],note:"孔子在匡地被围，颜渊落在后面。孔子说：「吾以女（汝）为死矣」——我以为你已经死了！颜渊答：「子在，回何敢死」——老师还在，我怎么敢死？"},{id:"ershisi",label:"二十四、以道事君，不可则止",showLabel:!0,sentences:[["季子然问：“仲由、冉求可谓大臣与？”子曰：“吾以子为异之问，曾由与求之问。所谓大臣者，以道事君，不可则止。今由与求也，可谓",{text:"具臣",glossary:"juchen"},"矣。”曰：“然则从之者与？”子曰：“弑父与君，亦不从也。”"]],note:"季子然问：「仲由、冉求可谓大臣与」——仲由、冉求可算大臣吗？孔子说：「吾以子为异之问，曾由与求之问」——我以为你要问别人，竟是问仲由与冉求。「所谓大臣者，以道事君，不可则止」——所谓大臣，是以道事君，行不通便辞去。「今由与求也，可谓具臣矣」——如今仲由、冉求，只可算「具臣」（备位之臣）。又问：「然则从之者与」——那么他们会盲从季氏吗？答：「弑父与君，亦不从也」——弑父弑君之事，他们也不会听从。"},{id:"ershiwu",label:"二十五、是故恶夫佞者",showLabel:!0,sentences:[["子路使子羔为费宰。子曰：“贼夫人之子。”子路曰：“有民人焉，有社稷焉，何必读书然后为学。”子曰：“是故恶夫佞者。”"]],note:"子路使子羔为费邑之宰。孔子说：「贼夫人之子」——这是害人家的子弟（未学而仕）。子路说：「有民人焉，有社稷焉，何必读书然后为学」——那里有百姓、有社稷，何必读书才算学？孔子说：「是故恶夫佞者」——所以我厌恶巧言强辩之人。"},{id:"ershiliu",label:"二十六、吾与点也",showLabel:!0,sentences:[["子路、曾皙、冉有、公西华侍坐，子曰：“以吾一日长乎尔，毋吾以也。居则曰‘不吾知也’如或知尔，则何以哉？”子路率尔而对曰：“千乘之国，摄乎大国之间，加之以师旅，因之以饥馑，由也为之，比及三年，可使有勇，且知方也。”夫子哂之。“求，尔何如？”对曰：“方六七十，如五六十，求也为之，比及三年，可使足民。如其礼乐，以俟君子。”“赤！尔何如？”对曰：“非曰能之，愿学焉。宗庙之事，如会同，端章甫，愿为小相焉。”“点，尔何如？”鼓瑟希，铿尔，舍瑟而作，对曰：“异乎三子者之撰。”子曰：“何伤乎？亦各言其志也。”曰：“暮春者，春服既成，冠者五六人，童子六七人，浴乎沂，风乎舞雩，咏而归。”夫子喟然叹曰：“吾与点也！”三子者出，曾皙后。曾皙曰：“夫三子者之言何如？”子曰：“亦各言其志也已矣。”曰：“夫子何哂由也？”曰：“为国以礼，其言不让，是故哂之。”“唯求则非邦也与？”“安见方六七十、如五六十而非邦也者？”“唯赤则非邦也与？”“宗庙会同，非诸侯而何？赤也为之小，孰能为之大？”"]],note:"子路、曾皙、冉有、公西华侍坐。孔子说：「以吾一日长乎尔，毋吾以也」——我比你们痴长几岁，不要因此不敢言。「居则曰『不吾知也』，如或知尔，则何以哉」——你们平日常说「没人了解我」，若有人了解你们，打算如何？子路率尔而答：千乘之国夹在大国之间，外有师旅、内有饥馑，我去治理，三年可使百姓有勇且知方。孔子微微一笑。冉有说：方圆六七十里或五六十里之地，我去治理，三年可使百姓富足，礼乐则待君子。公西华说：不敢说能行，但愿学之；宗庙之事、诸侯会同，愿做个小相。曾皙弹瑟之声渐稀，铿然舍瑟而答：暮春三月，春服既成，与五六位成人、六七位童子，浴乎沂、风乎舞雩，咏而归。孔子长叹：「吾与点也」——我赞同曾点啊！三人出后，曾皙问那三位之言，孔子一一评之：治国以礼，其言不让，故笑之；岂见方六七十非邦？宗庙会同非诸侯之事而何？若公西赤只做小相，谁能做大相？——此章为全书最长的一章，也是孔门志向最生动的一幅画。"}],r=[{id:"jian-jian",term:"间",pinyin:"jiàn",meaning:"非议、离间。人不间于其父母昆弟之言：别人对他父母兄弟称许他的话没有非议。"},{id:"guo",term:"椁",pinyin:"guǒ",meaning:"外棺。古人棺外再加椁，厚葬的标志之一。"},{id:"tong",term:"恸",pinyin:"tòng",meaning:"极度悲伤、大哭。"},{id:"yinyinru2",term:"訚訚如",pinyin:"yín yín rú",meaning:"和悦而正直的样子。"},{id:"hanghangru",term:"行行如",pinyin:"hàng hàng rú",meaning:"刚强、勇武的样子。"},{id:"kankanru2",term:"侃侃如",pinyin:"kǎn kǎn rú",meaning:"刚直而和乐的样子。"},{id:"guoyoubuji",term:"过犹不及",pinyin:"guò yóu bù jí",meaning:"过了头，和做得不够一样不好。这是中庸之道的经典表述。"},{id:"pi-pian",term:"辟",pinyin:"pì",meaning:"偏、偏激（一说「辟」为「僻」，邪僻）。"},{id:"yan",term:"喭",pinyin:"yàn",meaning:"粗鲁、莽撞。"},{id:"lvkong",term:"屡空",pinyin:"lǚ kòng",meaning:"常常穷困、空乏。"},{id:"yizelvzhong",term:"亿则屡中",pinyin:"yì zé lǚ zhòng",meaning:"亿：同「臆」，推测（一说「意」为猜测行情）。子贡经商，猜度行情常常猜中。"},{id:"du",term:"笃",pinyin:"dǔ",meaning:"诚恳、笃实。论笃是与：听到诚恳的言论就赞许。"},{id:"juchen",term:"具臣",pinyin:"jù chén",meaning:"备位充数的臣子（有才具而无大节，不足以称大臣）。"}];return(b,e)=>{const o=n("DaoTextReading"),l=n("DaoKeywordCards");return h(),u("div",null,[e[0]||(e[0]=i('<h1 id="论语·先进" tabindex="-1">论语·先进 <a class="header-anchor" href="#论语·先进" aria-label="Permalink to &quot;论语·先进&quot;">​</a></h1><h2 id="【原典层】原文" tabindex="-1">【原典层】原文 <a class="header-anchor" href="#【原典层】原文" aria-label="Permalink to &quot;【原典层】原文&quot;">​</a></h2><p>《先进》二十六章，是<strong>孔子晚年对弟子的回忆与评点</strong>。开头「先进于礼乐，野人也」「从我于陈蔡者，皆不及门也」，已带出缅怀的语气；接着列出「四科十哲」（德行、言语、政事、文学），是《论语》中唯一的一份弟子名录。</p><p>这一篇有几处极重：颜渊死时孔子连说「天丧予」，又哭之恸——<strong>「非夫人之为恸而谁为」</strong>；子路问事鬼神与死，孔子答「未能事人，焉能事鬼」「未知生，焉知死」；子贡问师与商孰贤，孔子答**「过犹不及」<strong>；以及第二十二章，同一个人问同一句话，孔子对子路说「有父兄在」，对冉有说「闻斯行之」——</strong>「求也退，故进之；由也兼人，故退之」**，因材施教四字，全在这一次里。</p><p>末章「侍坐」是《论语》中最长的一章，也是气象最开阔的一章：四个人各言其志，唯独曾皙说「浴乎沂，风乎舞雩，咏而归」，孔子叹道——<strong>「吾与点也！」</strong></p><p>默认竹简沉浸通读；切「经典阅读」可点生词。</p>',6)),a(o,{colophon:"先进第十一 · 二十六章",tone:"ink",sections:s,glossary:r,"default-mode":"slips","aria-label":"论语·先进 原文"}),e[1]||(e[1]=t("h2",{id:"【原典层】注音与字词",tabindex:"-1"},[d("【原典层】注音与字词 "),t("a",{class:"header-anchor",href:"#【原典层】注音与字词","aria-label":'Permalink to "【原典层】注音与字词"'},"​")],-1)),a(l,{items:[{term:"间",pinyin:["jiàn"],meaning:"非议、离间。人不间于其父母昆弟之言：别人对他父母兄弟称许他的话没有非议。"},{term:"椁",pinyin:["guǒ"],meaning:"外棺。古人棺外再加椁，厚葬的标志之一。"},{term:"恸",pinyin:["tòng"],meaning:"极度悲伤、大哭。"},{term:"訚訚如",pinyin:["yín","yín","rú"],meaning:"和悦而正直的样子。"},{term:"行行如",pinyin:["hàng","hàng","rú"],meaning:"刚强、勇武的样子。"},{term:"侃侃如",pinyin:["kǎn","kǎn","rú"],meaning:"刚直而和乐的样子。"},{term:"过犹不及",pinyin:["guò","yóu","bù","jí"],meaning:"过了头，和做得不够一样不好。这是中庸之道的经典表述。"},{term:"辟",pinyin:["pì"],meaning:"偏、偏激（一说「辟」为「僻」，邪僻）。"},{term:"喭",pinyin:["yàn"],meaning:"粗鲁、莽撞。"},{term:"屡空",pinyin:["lǚ","kòng"],meaning:"常常穷困、空乏。"},{term:"亿则屡中",pinyin:["yì","zé","lǚ","zhòng"],meaning:"亿：同「臆」，推测（一说「意」为猜测行情）。子贡经商，猜度行情常常猜中。"},{term:"笃",pinyin:["dǔ"],meaning:"诚恳、笃实。论笃是与：听到诚恳的言论就赞许。"},{term:"具臣",pinyin:["jù","chén"],meaning:"备位充数的臣子（有才具而无大节，不足以称大臣）。"}]}),e[2]||(e[2]=i('<p>全篇生词的完整释义在<a href="/Dao/reference/glossary/">字词释义字典</a>中统一维护。</p><h2 id="【解读层】三问解读" tabindex="-1">【解读层】三问解读 <a class="header-anchor" href="#【解读层】三问解读" aria-label="Permalink to &quot;【解读层】三问解读&quot;">​</a></h2><h3 id="象-这一篇在说什么" tabindex="-1">象：这一篇在说什么 <a class="header-anchor" href="#象-这一篇在说什么" aria-label="Permalink to &quot;象：这一篇在说什么&quot;">​</a></h3><p>《先进》二十六章，重心是<strong>孔子与弟子的关系</strong>——而且是晚年的孔子在回望。所以这一篇里有最深的悲痛（颜渊死，天丧予），有最直白的评点（柴也愚，参也鲁），有最见教的智慧（求也退故进之，由也兼人故退之），也有最开阔的一段（侍坐章「吾与点也」）。</p><p>它的结构松散，但有一条暗线：<strong>孔子看人，从来不是一把尺子。</strong> 同一个人问同一句话，他给相反的答案，因为他看的是问话的人，不是问话本身。子路刚强，就压他；冉求退让，就推他。曾皙说的志向听起来最无用（洗澡吹风唱歌），孔子却说「吾与点也」。</p><h3 id="理-为什么值得读" tabindex="-1">理：为什么值得读 <a class="header-anchor" href="#理-为什么值得读" aria-label="Permalink to &quot;理：为什么值得读&quot;">​</a></h3><ul><li><strong>「过犹不及」四个字，是中庸之道最简的表述</strong>：不是折中，而是<strong>每一种德性都有它的恰当度量</strong>。过头与不够，同样偏离。</li><li><strong>它给出了「因材施教」的完整样本</strong>：第二十二章里，孔子把「同问异答」的理由讲得清清楚楚——<strong>答案要配人，不是配问题。</strong></li><li><strong>它直面「死」与「鬼神」</strong>：「未能事人，焉能事鬼」「未知生，焉知死」——<strong>孔子不否认它们，只是把次序摆在前面</strong>：先把活着的人和当下的事做好。</li><li><strong>它写下了最深的师生之情</strong>：「天丧予」「非夫人之为恸而谁为」「回也视予犹父也」——<strong>这些话让孔子从圣人变成了一个人。</strong></li><li><strong>「吾与点也」给出了另一种价值</strong>：前面三个人说的都是治国理政，曾皙说的是洗澡吹风唱歌。孔子偏偏赞同他——<strong>这不是否定事功，而是承认「安居乐俗」本身也是值得的志向。</strong></li></ul><h3 id="用-今日可用之处" tabindex="-1">用：今日可用之处 <a class="header-anchor" href="#用-今日可用之处" aria-label="Permalink to &quot;用：今日可用之处&quot;">​</a></h3><ol><li><strong>用「过犹不及」检查自己的用力方式</strong>：我是「师也过」，还是「商也不及」？<strong>找到自己容易偏的那一端，往回拉一点。</strong></li><li><strong>用「同问异答」的思路做沟通</strong>：给建议前先判断对方的性格——<strong>对退缩的人推一把，对莽撞的人压一压。</strong></li><li><strong>把「未知生，焉知死」当成次序的提醒</strong>：与其纠结终极问题，不先把眼前的人和事处理好。</li><li><strong>允许「无用」的志向</strong>：「浴乎沂，风乎舞雩，咏而归」——生活里要留一部分不产出、不功利的时间。<strong>孔子都点头了。</strong></li><li><strong>对朋友要敢说真话，也要会退让</strong>：「非吾徒也，小子鸣鼓而攻之」是极重的批评，「由也升堂矣，未入于室也」又是护着弟子——<strong>批评的分寸，是看人来的。</strong></li></ol><h2 id="【解读层】现代重述" tabindex="-1">【解读层】现代重述 <a class="header-anchor" href="#【解读层】现代重述" aria-label="Permalink to &quot;【解读层】现代重述&quot;">​</a></h2><p>《先进》这一篇里的孔子，是晚年的孔子。</p><p>他回忆当年跟着他在陈蔡之间挨饿的学生，说他们如今都不在身边了。他失去颜回时哭了，说「老天要我的命啊」，然后被人提醒「您太悲痛了」，他反问：「我不为这个人悲痛，还为谁悲痛？」</p><p>这一篇里我最喜欢两个地方。一个是第二十二章：子路问「听到就去做吗」，他说「有父兄在」；冉有问同样一句话，他说「听到就去做」。别人不解，他解释：<strong>冉有平时退缩，所以我推他一把；子路好勇过人，所以我压压他。</strong></p><p>另一个是最后一章。四个人谈志向，前三个都在谈治国。最后曾皙说：暮春三月，穿上春衣，和几个大人小孩在沂水里洗个澡，在台上吹吹风，唱着歌回来。孔子长叹一声——<strong>「吾与点也！」</strong></p><p>两千五百年了，四个人的抱负，人们记得的是第四个。</p><h2 id="【解读层】我的理解" tabindex="-1">【解读层】我的理解 <a class="header-anchor" href="#【解读层】我的理解" aria-label="Permalink to &quot;【解读层】我的理解&quot;">​</a></h2><blockquote><p>待补——这一节留给自己的读后想法。</p></blockquote><p>可以按这几条慢慢写：</p><ul><li>「过犹不及」——我在哪件事上偏「过」，在哪件事上偏「不及」？</li><li>「求也退，故进之；由也兼人，故退之」——我给别人建议时，有没有按对方的性格调整过方式？</li><li>「未知生，焉知死」——我有没有为一些终极问题消耗了太多本该用于当下的精力？</li><li>「吾与点也」——如果只让我说自己的志向，不谈工作成就，我会说什么？孔子会赞同吗？</li></ul><h2 id="关联" tabindex="-1">关联 <a class="header-anchor" href="#关联" aria-label="Permalink to &quot;关联&quot;">​</a></h2><ul><li><a href="/Dao/lizhimingde/sishu-wujing/lunyu/">论语总览</a></li><li><a href="/Dao/lizhimingde/sishu-wujing/">四书五经总览</a></li><li>同栏目：<a href="/Dao/lizhimingde/sishu-wujing/daxue/">大学</a> · <a href="/Dao/lizhimingde/sishu-wujing/zhongyong/">中庸</a> · <a href="/Dao/lizhimingde/sishu-wujing/mengzi/">孟子</a></li><li>上篇：<a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-10">论语·乡党</a>　下篇：<a href="/Dao/lizhimingde/sishu-wujing/lunyu/chapter-12">论语·颜渊</a></li><li>参考：《论语》朱熹《四书章句集注·论语集注》；杨伯峻《论语译注》</li></ul>',21))])}}});export{c as __pageData,w as default};
